// inventory · кейс inv-09 (.qa/tests/inventory/) — #6cdf674f «קליטת מלאי: מפת המחסן לבחירת המקום» (עבר QA 2026-10-14).
// Окно «הוספת פריט למלאי» из каталога: карта склада, места товара выделены (opacity 1) и подписаны, остальное серое (opacity < 1)
// и не выбирается; место выбирается списком «מקום היעד», кнопками «ארון X» → полка и касанием по месту на карте — всё синхронно,
// отметка «נבחר» (тёмная подпись, g[data-callout-chosen]) только у выбранного; код в «מקום הקליטה» в одну строку.
// Вход с карты склада («הוספת פריט למדף») — без карты (комментарий владельца 07.10).
// Товар «QA-AUTO-6cdf-<d|m>-<ts>» в 3 свободных «ריק» местах (найдены на карте во время прогона): десктоп — шкаф H, iPhone — C/A
// (разные шкафы — проекты идут параллельно). ⚠️ Приёмка 1 шт. (десктоп) → неудаляемая запись «קליטה» в יומן תנועות.
// Уборка — «הסרה מהמקום» во всех местах, удаление товара, места снова «ריק».
// Не запускать одновременно с location-cell-multi-places / inventory-lifecycle (общие данные склада).
import { test, expect, Page, Locator, TestInfo } from '@playwright/test';
import * as H from './_places';

test.use({ storageState: H.ADMIN });
test.describe.configure({ mode: 'serial' });

const TS = Date.now().toString().slice(-7);
const created = new Set<string>();
const used: H.Used = new Map();
let P = '';
let places: H.Place[] = [];

const HINT = 'המקומות שהמוצר משויך אליהם מודגשים; שאר המחסן אפור ואינו ניתן לבחירה.';
const dialog = (page: Page) => page.getByRole('dialog');
const map = (dlg: Locator) => dlg.getByRole('application', { name: 'קנבס המחסן' });
const placeSelect = (dlg: Locator) => dlg.getByRole('combobox', { name: 'מקום היעד' });
/** Зона касания подписи места товара на карте (у серых мест её нет). */
const placeHit = (dlg: Locator, shelf: string) => map(dlg).locator(`rect[pointer-events="all"][aria-label="${shelf}"]`);
const chosenLabel = (dlg: Locator) => map(dlg).locator('g[data-callout-chosen="true"]');
const isTouch = (info: TestInfo) => Boolean((info.project.use as { hasTouch?: boolean }).hasTouch);

/** Вход К1 — клик по числу «במלאי» в каталоге. */
async function openFromQty(page: Page) {
  await H.findProduct(page, P);
  await H.qtyBtn(page, P).click();
  const dlg = dialog(page);
  await expect(dlg.getByRole('heading', { name: 'הוספת פריט למלאי' })).toBeVisible();
  return dlg;
}

/** Карта показана: ровно места товара яркие (opacity 1) и выбираемые, с подписью-названием; остальные места серые. */
async function expectHighlight(dlg: Locator) {
  await expect(map(dlg)).toBeVisible({ timeout: 20_000 });
  await expect(dlg.getByText(HINT)).toBeVisible();
  const shapes = await map(dlg).evaluate((svg) =>
    [...svg.querySelectorAll('rect[data-shape-kind="location"][opacity]')].map((r) => ({
      label: r.getAttribute('aria-label') ?? '',
      op: Number(r.getAttribute('opacity')),
    })),
  );
  const bright = shapes.filter((s) => s.op >= 1).map((s) => s.label).sort();
  expect(bright, 'выделены ровно места товара').toEqual(places.map((p) => `ארון ${p.cabinet} · ${p.shelf}`).sort());
  const gray = shapes.filter((s) => s.op < 1);
  expect(gray.length, 'остальные места склада серые').toBeGreaterThan(10);
  for (const g of gray) expect(g.op, `серое место ${g.label}`).toBeLessThanOrEqual(0.5);
  // подпись с названием и зона выбора — только у мест товара
  await expect(map(dlg).locator('rect[pointer-events="all"][data-shape-kind="location"]')).toHaveCount(places.length);
  for (const p of places) {
    await expect(placeHit(dlg, p.shelf)).toHaveCount(1);
    await expect(map(dlg).locator('text').filter({ hasText: new RegExp(`^${p.shelf}$`) }).first()).toBeAttached();
  }
}

/** Выбрано место pl: список, «נבחר:», «מקום הקליטה» (код одной строкой), отметка «נבחר» на карте только у него. */
async function expectChosen(dlg: Locator, pl: H.Place) {
  await expect(placeSelect(dlg).locator('option:checked')).toContainText(`(${pl.code})`);
  await expect(dlg.getByText(/^נבחר:.*\([^)]+\)$/)).toContainText(`ארון ${pl.cabinet} · ${pl.shelf} (${pl.code})`);
  await expect(dlg).toContainText(`מקום הקליטה`);
  const code = dlg.locator('bdi').filter({ hasText: new RegExp(`^${pl.code}$`) });
  await expect(code).toHaveCount(1);
  expect(await code.evaluate((e) => e.getClientRects().length), `код ${pl.code} в «מקום הקליטה» одной строкой`).toBe(1);
  await expect(chosenLabel(dlg)).toHaveCount(1);
  await expect(chosenLabel(dlg).locator('text')).toHaveText(pl.shelf);
}

/** Центр серого места на карте, далеко (>30px) от подписей мест товара. */
async function farGrayPoint(dlg: Locator) {
  return map(dlg).evaluate((svg) => {
    const labels = [...svg.querySelectorAll('rect[pointer-events="all"]')].map((r) => r.getBoundingClientRect());
    const box = svg.getBoundingClientRect();
    const far = (b: DOMRect) =>
      labels.every((c) => b.right < c.left - 30 || b.left > c.right + 30 || b.bottom < c.top - 30 || b.top > c.bottom + 30);
    for (const g of svg.querySelectorAll('rect[data-shape-kind="location"][opacity]')) {
      if (Number(g.getAttribute('opacity')) >= 1) continue;
      const b = g.getBoundingClientRect();
      if (b.width < 8 || b.height < 4 || b.left < box.left || b.right > box.right || b.top < box.top || b.bottom > box.bottom) continue;
      if (!far(b)) continue;
      return { label: g.getAttribute('aria-label'), x: b.left + b.width / 2, y: b.top + b.height / 2 };
    }
    return null;
  });
}

test.describe('inventory — מפת המחסן בחלון קליטת המלאי (#6cdf674f)', () => {
  test.beforeAll(async ({ browser }, info) => {
    test.setTimeout(420_000);
    const mobile = info.project.name !== 'tests';
    P = `QA-AUTO-6cdf-${mobile ? 'm' : 'd'}-${TS}`;
    const ctx = await browser.newContext({ storageState: H.ADMIN, locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    const page = await ctx.newPage();
    try {
      places = await H.pickEmptyPlaces(page, 3, mobile ? ['C', 'A'] : ['H']);
      await H.createProduct(page, P, `QA6CDF${mobile ? 'M' : 'D'}${TS}`, created);
      H.track(used, P, ...places);
      await H.bindPlace(page, P, places[0]);
      for (const pl of places.slice(1)) await H.bindPlace(page, P, pl, true);
    } finally {
      await ctx.close();
    }
  });

  test.afterAll(async ({ browser }) => {
    test.setTimeout(400_000);
    await H.cleanup(browser, created, used);
  });

  test('כניסה מהכמות «במלאי»: מוצגת מפת המחסן — 3 מקומות המוצר מודגשים עם שם, השאר באפור; אחד ממקומות המוצר נבחר #6cdf674f @desktop @data', async ({ page }) => {
    test.skip(places.length < 3, 'товар не подготовлен');
    const dlg = await openFromQty(page);
    await expectHighlight(dlg);
    const checked = (await placeSelect(dlg).locator('option:checked').innerText()).trim();
    const pre = places.find((p) => checked.includes(`(${p.code})`));
    expect(pre, `по умолчанию выбрано место товара, а не «${checked}»`).toBeDefined();
    await expectChosen(dlg, pre!);
    await dlg.getByRole('button', { name: 'ביטול' }).click();
    await expect(dlg).toHaveCount(0);
  });

  test('בחירת מקום מהרשימה, מהמפה ומכפתורי «ארון» — הכל מסונכרן, סימון «נבחר» רק במקום שנבחר; לחיצה על מקום אפור לא בוחרת #6cdf674f @desktop @data', async ({ page }) => {
    test.skip(places.length < 3, 'товар не подготовлен');
    const dlg = await openFromQty(page);
    await expect(map(dlg)).toBeVisible({ timeout: 20_000 });

    // список «לאיזה מקום»
    for (const pl of [places[1], places[2], places[0]]) {
      await placeSelect(dlg).selectOption({ label: await H.placeOption(dlg, pl.code) });
      await expectChosen(dlg, pl);
    }
    // клик по месту на карте
    for (const pl of [places[2], places[1]]) {
      await placeHit(dlg, pl.shelf).click();
      await expectChosen(dlg, pl);
    }
    // кнопки «ארון X» → полка
    await dlg.getByRole('button', { name: `ארון ${places[0].cabinet}`, exact: true }).click();
    await dlg.getByRole('button', { name: places[0].shelf, exact: true }).click();
    await expect(dlg.getByRole('button', { name: places[0].shelf, exact: true })).toHaveAttribute('aria-pressed', 'true');
    await expectChosen(dlg, places[0]);

    // серое место (вдали от подписей мест товара) — выбор не меняется, окно открыто
    const gray = await farGrayPoint(dlg);
    expect(gray, 'на карте есть серое место вдали от мест товара').not.toBeNull();
    await page.mouse.click(gray!.x, gray!.y);
    await expectChosen(dlg, places[0]);
    await expect(dlg.getByRole('heading', { name: 'הוספת פריט למלאי' })).toBeVisible();

    await dlg.getByRole('button', { name: 'ביטול' }).click();
    await expect(dlg).toHaveCount(0);
  });

  test('כניסה מכפתור «קליטת מלאי» בכותרת: אין מפה לפני בחירת מוצר; אחרי בחירה — אותה מפה עם מקומות המוצר #6cdf674f @desktop @data', async ({ page }) => {
    test.skip(places.length < 3, 'товар не подготовлен');
    await page.goto('/catalog');
    await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible({ timeout: 30_000 });
    await page.getByRole('button', { name: 'קליטת מלאי', exact: true }).click();
    const dlg = dialog(page);
    await expect(dlg.getByRole('heading', { name: 'הוספת פריט למלאי' })).toBeVisible();
    await expect(map(dlg)).toHaveCount(0);
    await dlg.getByRole('combobox', { name: 'מוצר' }).fill(P);
    await dlg.getByRole('option', { name: new RegExp(P) }).first().click();
    await expectHighlight(dlg);
    await placeHit(dlg, places[2].shelf).click();
    await expectChosen(dlg, places[2]);
    await dlg.getByRole('button', { name: 'ביטול' }).click();
    await expect(dlg).toHaveCount(0);
  });

  test('כניסה ממפת המחסן (מקום → «הוספת פריט למדף»): חלון הקליטה בלי מפה, המקום שנלחץ נבחר #6cdf674f @desktop @data', async ({ page }) => {
    test.skip(places.length < 3, 'товар не подготовлен');
    await H.openPlace(page, places[1]);
    await H.side(page).getByRole('button', { name: 'הוספת פריט למדף' }).click();
    const dlg = dialog(page);
    await expect(dlg.getByRole('heading', { name: 'הוספת פריט למלאי' })).toBeVisible();
    await dlg.getByRole('combobox', { name: 'מוצר' }).fill(P);
    await dlg.getByRole('option', { name: new RegExp(P) }).first().click();
    await expect(placeSelect(dlg).locator('option:checked')).toContainText(`(${places[1].code})`);
    await expect(map(dlg)).toHaveCount(0);
    await expect(dlg.getByText(HINT)).toHaveCount(0);
    await dlg.getByRole('button', { name: 'ביטול' }).click();
    await expect(dlg).toHaveCount(0);
  });

  test('קליטה למקום שנבחר במפה: «1 של … נקלטו למדף <קוד>.», «במלאי» 1, במקום — 1 #6cdf674f @desktop @data', async ({ page }) => {
    test.setTimeout(180_000);
    test.skip(places.length < 3, 'товар не подготовлен');
    const target = places[1];
    const dlg = await openFromQty(page);
    await expect(map(dlg)).toBeVisible({ timeout: 20_000 });
    await placeHit(dlg, target.shelf).click();
    await expectChosen(dlg, target);
    await dlg.getByRole('spinbutton', { name: 'כמות', exact: true }).fill('1');
    await dlg.getByRole('button', { name: 'הוספה' }).click();
    // имя товара в тосте — в bidi-изоляторах U+2068/U+2069
    await expect(page.getByText(new RegExp(`^1 של .?${P}.? נקלטו למדף ${target.code}\\.$`))).toBeVisible({ timeout: 15_000 });
    await expect(dlg).toHaveCount(0, { timeout: 15_000 });
    await H.expectStock(page, P, 1);
    await H.openPlace(page, target);
    expect(await H.qtyInPlacePanel(page, P)).toBe(1);
  });

  test('iPhone: מפה בחלון הקליטה — מקומות המוצר מודגשים, השאר אפור; בחירה ברשימה ובנגיעה במפה מסומנת על המקום; קוד ב«מקום הקליטה» בשורה אחת #6cdf674f @iphone @data', async ({ page }, info) => {
    test.setTimeout(180_000);
    test.skip(places.length < 3, 'товар не подготовлен');
    const dlg = await openFromQty(page);
    await expectHighlight(dlg);
    for (const pl of places) {
      await placeSelect(dlg).selectOption({ label: await H.placeOption(dlg, pl.code) });
      await expectChosen(dlg, pl);
    }
    for (const pl of [places[0], places[2]]) {
      const hit = placeHit(dlg, pl.shelf);
      if (isTouch(info)) await hit.tap();
      else await hit.click();
      await expectChosen(dlg, pl);
    }
    await dlg.getByRole('button', { name: 'ביטול' }).click();
    await expect(dlg).toHaveCount(0);
  });
});
